{
  "name": "simplified_stable_pairwise_loss",
  "intuition": "Removed unused variables and redundant scaling, simplified to just a difference of weighted log probabilities with clamping to prevent numerical instability. Only uses required keys: log_prob_w, log_prob_l, weight, and advantage_gap as a quality signal. The loss computes a stable log-sigmoid on the difference (log_prob_w - log_prob_l) scaled by advantage_gap clamped to [-20,20], ensuring numerical stability and proper gradient flow while keeping the semantics clear and straightforward.",
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_gap = batch['advantage_gap']\n    raw_diff = lpw - lpl\n    scaled_diff = ops.clamp(ops.mul(raw_diff, adv_gap), -20.0, 20.0)\n    loss = -ops.logsigmoid(scaled_diff)\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()",
