{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss encourages the model to prefer pairs where the advantage is higher for the better option, scaled by the cost gap. Using advantage signals amplifies meaningful preference differences, while the cost gap ensures the preference aligns with the true cost difference. This combination promotes selection of options with improved outcomes, adapting well to RL4CO objectives.",
  "pseudocode": "loss = -mean over pairs [logsigmoid((advantage_w - advantage_l) * cost_gap)]",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "advantage_cost",
    "link_family": "pairwise",
    "agg_family": "mean",
    "constraint_family": "cost_gap"
  },
  "operators_used": ["logsigmoid", "mul", "sub", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    cost_gap = batch['cost_gap']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n\n    pref_score = ops.logsigmoid(ops.mul(ops.sub(advantage_w, advantage_l), cost_gap))\n    loss = -ops.mean(ops.mul(pref_score, weight))\n    return loss"
}

{
  "name": "pairwise_rankgap_tanh_advantage",
  "intuition": "This loss leverages the advantage signals to compute a ranking gap, then applies a smooth tanh link to emphasize larger gaps in preference, encouraging the model to prioritize better-ranked pairs with a differentiable shape. Summation over pairs weighted by importance produces a scalar loss that encourages ranking consistency aligned with advantage differentials.",
  "pseudocode": "rank_gap = advantage_w - advantage_l\nscaled_gap = tanh(beta * rank_gap)\nloss_per_pair = weight * relu(-scaled_gap)\nloss = sum(loss_per_pair) / sum(weight + epsilon)",
  "hyperparams": {
    "paradigm_family": "pairwise_rankgap",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "weighted_sum",
    "constraint_family": "relu_nonneg"
  },
  "operators_used": ["sub", "tanh", "mul", "relu", "sum", "add"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    beta = float(extra.get('hyperparams', {}).get('beta', 2.0))\n    rank_gap = ops.sub(advantage_w, advantage_l)\n    scaled_gap = ops.tanh(ops.mul(beta, rank_gap))\n    negative_scaled_gap = ops.mul(-1.0, scaled_gap)\n    loss_per_pair = ops.mul(weight, ops.relu(negative_scaled_gap))\n    loss = ops.div(ops.sum(loss_per_pair), ops.add(ops.sum(weight), 1e-8))\n    return loss"
}

