{
  "name": "pairwise_logsigmoid_delta",
  "intuition": "This loss combines the log-sigmoid of the difference between model log probabilities and a delta signal to emphasize pairwise ranking consistency while incorporating the delta to reflect the reliability of the preference. Clamping prevents extreme values, ensuring stable gradients. It encourages the model to order pairs correctly according to the delta signal, which is useful when preference confidence varies.",
  "pseudocode": "loss = -logsigmoid(clamp(alpha * (log_prob_w - log_prob_l) + beta * delta_signal, -20, 20)); final_loss = sum(weighted_loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "delta_signal",
    "link_family": "logsigmoid",
    "agg_family": "sum",
    "constraint_family": "clamp_stabilized",
    "other_hparams": "optional"
  },
