  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "delta_signal"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    delta_signal = batch['delta_signal']\n    alpha = float(extra.get('alpha', 1.0))\n    beta = float(extra.get('beta', 0.1))\n    x = ops.add(ops.mul(alpha, ops.sub(lpw, lpl)), ops.mul(beta, delta_signal))\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = ops.neg(ops.logsigmoid(x))\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return ops.sum(loss)"
}

